const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hitPoint=new THREE.Vector3();
function distanceToRoute(x,z){let best=999;for(let i=0;i<80;i++){const p=curve.getPointAt(i/80);best=Math.min(best,Math.hypot(p.x-x,p.z-z));}return best}
function creatureTower(type,x,z){const def=roster.find(t=>t.id===type),root=group(scene,[x,0,z]);const base=mesh(new THREE.CylinderGeometry(.63,.74,.28,12),mat('#d7d0b6'),root,[0,.15,0]);mesh(new THREE.CylinderGeometry(.52,.61,.18,12),mat(def.color),root,[0,.34,0]);const mon=makeCreature(root,def.kind,.64);mon.position.y=.35;mon.userData.tower=true;const halo=mesh(new THREE.TorusGeometry(.8,.045,7,30),mat(def.color, .3,{emissive:def.color,emissiveIntensity:.24}),root,[0,.07,0]);halo.rotation.x=Math.PI/2;const range=mesh(new THREE.RingGeometry(5.5,5.57,48),mat(def.color,.7,{transparent:true,opacity:.22,side:THREE.DoubleSide}),root,[0,.04,0]);range.rotation.x=-Math.PI/2;range.visible=false;const tower={type,def,root,base,mon,range,halo,x,z,level:1,damage:def.damage,reach:def.range,rate:def.rate,cool:Math.random()*.4,invested:def.cost,targetMode:0,shots:0};root.userData.tower=tower;base.userData.tower=tower;mon.userData.tower=tower;towers.push(tower);return tower;}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),1900)}
function format(n){return Math.floor(n).toLocaleString('pt-BR')}
function updateHud(){ $('#cash').textContent=format(cash);$('#lives').textContent=lives;$('#round').textContent=round;$('#waveCount').innerHTML=`${String(Math.min(round+1,20)).padStart(2,'0')} <i>/ 20</i>`;$('#startWave').disabled=phase==='wave';$('#mobileWave').disabled=phase==='wave';$('#startWave').innerHTML=phase==='wave'?'ONDA EM CURSO <b>…</b>':'COMEÇAR ONDA <b>→</b>';$('#mobileWave').textContent=phase==='wave'?'● EM CURSO':'▶ ONDA';$('#waveTitle').textContent=phase==='wave'?'Balões a caminho!':round===0?'Balões de treino':`Onda ${round+1} preparada`;$('#waveInfo').textContent=phase==='wave'?`${waveRemaining} balões na trilha`:`${8+Math.min(round,19)*3} balões • velocidade normal`;$('#waveProgress').style.width=phase==='wave'?`${100*(1-waveRemaining/Math.max(1,waveTotal))}%`:'0%';$('#speedBtn').textContent=`▶ ${speed}×`}
function selectTower(t){if(selectedTower)selectedTower.range.visible=false;selectedTower=t;selectedType=null;$('#shop').hidden=true;$('#selectedCard').hidden=false;t.range.visible=true;t.range.geometry.dispose();t.range.geometry=new THREE.RingGeometry(t.reach-.035,t.reach+.035,48);$('#selectedIcon').textContent=t.def.glyph;$('#selectedIcon').style.background=t.def.color;$('#selectedName').textContent=t.def.name;$('#selectedLevel').textContent=`NÍVEL ${t.level} · ALCANCE ${t.reach.toFixed(1)}`;$('#upgradeName').textContent=t.level<4?'Melhorar':'Nível máximo';$('#upgradeDesc').textContent=t.level===1?'Dano +1 · Alcance +1':t.level===2?'Dano +1 · Disparo veloz':t.level===3?'Dano +2 · Alcance +1':'Este parceiro está no máximo';const cost=Math.round(t.def.cost*(.75+t.level*.7));$('#upgradeCost').textContent=t.level<4?`$${cost}`:'MAX';$('#upgradeBtn').disabled=t.level>=4||cash<cost;$('#sellValue').textContent=`$${Math.floor(t.invested*.72)}`;$('#targetBtn').textContent=`ALVO: ${['PRIMEIRO','ÚLTIMO','FORTE'][t.targetMode]}`;}
function clearSelection(){if(selectedTower)selectedTower.range.visible=false;selectedTower=null;$('#selectedCard').hidden=true;$('#shop').hidden=false;}
function placeTower(type,x,z){const def=roster.find(t=>t.id===type);if(!def)return;if(distanceToRoute(x,z)<1.9){showToast('Muito perto do caminho dos balões!');return}if(Math.abs(x)>19||Math.abs(z)>14){showToast('Escolha um espaço dentro do prado.');return}if(towers.some(t=>Math.hypot(t.x-x,t.z-z)<1.35)){showToast('Deixe um pouco de espaço entre as torres.');return}if(cash<def.cost){showToast('Moedas insuficientes!');return}cash-=def.cost;const tower=creatureTower(type,x,z);selectedType=null;document.querySelectorAll('.tower-card').forEach(e=>e.classList.remove('active'));$('#hint').classList.remove('show');selectTower(tower);updateHud();showToast(`${def.name} entrou para a equipe!`)}
function chooseType(type){if(selectedType===type){selectedType=null;$('#hint').classList.remove('show');document.querySelectorAll('.tower-card').forEach(e=>e.classList.remove('active'));return}if(selectedTower)clearSelection();selectedType=type;document.querySelectorAll('.tower-card').forEach(e=>e.classList.toggle('active',e.dataset.id===type));$('#hint').classList.add('show');$('#shop').hidden=false;}
function buildShop(){const list=$('#towerList');roster.forEach((t,i)=>{const b=document.createElement('button');b.className='tower-card';b.dataset.id=t.id;b.innerHTML=`<span class="tower-glyph" style="color:${t.color}">${t.glyph}</span><span class="tower-name">${t.name}</span><span class="tower-cost">◈ ${t.cost}</span>`;b.title=t.desc;b.onclick=()=>chooseType(t.id);list.appendChild(b)})}
buildShop();updateHud();

let spawnPlans=[];const balloonMats={red:'#f05b60',blue:'#5da9f6',green:'#56c973',yellow:'#f5d450',pink:'#ec7eb8',black:'#42434d',white:'#e9ecdf',lead:'#68757a',rainbow:'#bc78dc',ceramic:'#e6b994',moab:'#527aab'};
function makeBalloon(tier){let color=balloonMats[tier]||balloonMats.red;const root=group(scene,[0,0,0]);const bodyMat=mat(color,.28,{metalness:tier==='lead'?.5:0,emissive:color,emissiveIntensity:.07});let radius=tier==='moab'?.8:tier==='ceramic'?.42:.34;const body=mesh(new THREE.SphereGeometry(radius,14,12),bodyMat,root,[0,0,0],[.83,1.05,.78]);if(tier==='moab'){body.scale.set(1.45,.8,.85);for(let s of [-1,1])mesh(new THREE.BoxGeometry(.22,.2,.2),mat('#f3d577'),root,[s*.85,.09,0]);}else{mesh(new THREE.ConeGeometry(.075,.16,7),mat('#704e51'),root,[0,-radius-.06,0],[1,1,1]).rotation.x=Math.PI;mesh(new THREE.CylinderGeometry(.018,.012,.25,5),mat('#f2e7cb'),root,[0,-radius-.18,0]);if(['rainbow','ceramic'].includes(tier)){mesh(new THREE.TorusGeometry(radius*.76,.05,5,16),mat('#fff5d8',.3,{emissive:'#ffedb3',emissiveIntensity:.15}),root,[0,0,.03]);}}
const hp=({red:1,blue:2,green:3,yellow:4,pink:5,black:6,white:6,lead:8,rainbow:12,ceramic:18,moab:45})[tier]||1;return{root,body,tier,hp,maxHp:hp,progress:0,speed:tier==='pink'?.064:tier==='yellow'?.056:tier==='moab'?.025:.045+Math.min(round*.0007,.014),radius,alive:true};}
function tierForWave(index){if(round===20&&index===0)return'moab';if(round>=14&&index%9===0)return'ceramic';if(round>=11&&index%7===0)return'rainbow';if(round>=8&&index%5===0)return'lead';if(round>=6&&index%4===0)return'black';if(round>=4&&index%3===0)return'pink';if(round>=3&&index%4===0)return'yellow';if(round>=2&&index%3===0)return'green';if(round>=1&&index%3===0)return'blue';return'red';}
function startWave(){if(phase==='wave'||gameEnded)return;if(round>=20){finishGame(true);return}round++;phase='wave';spawnPlans=[];waveTotal=8+Math.min(round,19)*3;waveRemaining=waveTotal;for(let i=0;i<waveTotal;i++)spawnPlans.push(tierForWave(i));if(round===20)spawnPlans[0]='moab';spawnTimer=.45;$('#waveTitle').textContent=round===20?'Chefe da trilha: MOAB!':`Onda ${round} em andamento`;updateHud();}
function splitTier(tier){const tiers=['red','blue','green','yellow','pink','black','white','lead','rainbow','ceramic','moab'];return tiers[Math.max(0,tiers.indexOf(tier)-1)]}
function popBalloon(b,damage){if(!b.alive)return;b.hp-=damage;const ratio=Math.max(0,b.hp/b.maxHp);b.body.scale.set((b.tier==='moab'?1.45:.83)*(.75+.25*ratio), (b.tier==='moab'?.8:1.05)*(.75+.25*ratio),.78*(.75+.25*ratio));if(b.hp<=0){b.alive=false;scene.remove(b.root);const payout={red:1,blue:2,green:3,yellow:4,pink:5,black:6,white:6,lead:8,rainbow:10,ceramic:15,moab:50}[b.tier]||1;cash+=payout;heroCharge=Math.min(1,heroCharge+.012);makePopFx(b.root.position,b.tier==='moab'?'#d9faff':balloonMats[b.tier]);if(['ceramic','moab'].includes(b.tier)){let split=b.tier==='moab'?4:2;for(let i=0;i<split;i++){const child=makeBalloon(b.tier==='moab'?'ceramic':splitTier(b.tier));child.progress=b.progress;child.root.position.copy(b.root.position);bloons.push(child);waveRemaining++;}}waveRemaining=Math.max(0,waveRemaining-1);updateHud();}}
